function validate([n]) {
  if (!Number.isInteger(n) || n < 0 || n > 30) return 'n is an integer from 0 to 30.';
  return null;
}

reference:
function fib(n) {
  if (n < 2) {
    return n;
  }
  const dp = new Array(n + 1).fill(0);
  dp[1] = 1;
  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }
  return dp[n];
}

brute:
function fib(n) {
  // Plain recursion straight from the definition; fine for n <= 30.
  const f = k => (k < 2 ? k : f(k - 1) + f(k - 2));
  return f(n);
}

